     }
     if (listens(node, LISTEN_EDITING)) {
       transport.send(encodeEditingChanged(id, true));
     }
   });
   document.addEventListener("focusout", (event) => {
     const node = focusTarget(event);
     if (!transport.open || !node) {
       return;
     }
