     if (!transport.open) {
       return;
     }
     const textarea = target.closest<HTMLTextAreaElement>("textarea[data-pathland-id]");
     if (textarea) {
       transport.send(encodeTextChanged(Number(textarea.getAttribute("data-pathland-id")), textarea.value));
