     if (!input) {
       return;
     }
     const label = input.closest<HTMLElement>("label.pathland-textfield[data-pathland-id]");
     if (label) {
       transport.send(encodeTextChanged(Number(label.getAttribute("data-pathland-id")), input.value));
     }
   });
